class DB{
  open(version){return new Promise((res,rej)=>{const r=version?indexedDB.open(DB_NAME,version):indexedDB.open(DB_NAME);r.onupgradeneeded=()=>{const d=r.result;STORE_NAMES.forEach(name=>{if(!d.objectStoreNames.contains(name))d.createObjectStore(name,{keyPath:'id',autoIncrement:true})})};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);r.onblocked=()=>rej(new Error('Database upgrade blocked. Close other Slope tabs and reopen.'))})}
  async init(){let d=await this.open();const missing=STORE_NAMES.filter(n=>!d.objectStoreNames.contains(n));if(missing.length){const next=d.version+1;d.close();d=await this.open(next)}this.db=d}
  store(n,m='readonly'){return this.db.transaction(n,m).objectStore(n)}
  all(n){return new Promise((res,rej)=>{const r=this.store(n).getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
  get(n,id){return new Promise((res,rej)=>{const r=this.store(n).get(id);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
  add(n,o){return new Promise((res,rej)=>{const r=this.store(n,'readwrite').add(o);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
  put(n,o){return new Promise((res,rej)=>{const r=this.store(n,'readwrite').put(o);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
  del(n,id){return new Promise((res,rej)=>{const r=this.store(n,'readwrite').delete(id);r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
  clear(n){return new Promise((res,rej)=>{const r=this.store(n,'readwrite').clear();r.onsuccess=()=>res();r.onerror=()=>rej(r.error)})}
}
const db=new DB();

async function getSettings(){return (await db.all('settings'))[0]||{}}
async function saveSettings(p){const s=await getSettings();await db.put('settings',{...s,...p,id:s.id||1})}
async function seed(){
  if(!(await db.all('goals')).length)for(const x of GOALS)await db.add('goals',x);
  if(!(await db.all('phases')).length)for(const x of PHASES)await db.add('phases',x);
  let s=await getSettings();
  if(!s.id)await db.add('settings',{heightCm:178,birthDate:'1995-12-11',sex:'male',calorieLow:2150,calorieHigh:2300,externalCalories:2229,proteinFloor:120,proteinPreferred:140,externalProtein:112,stepTarget:8500,aiModel:'gpt-5.6',coachMemory:{themes:['Rebuilding consistency after time away'],testing:[],decisions:['Keep the programme full-body while ski specificity rises gradually'],watch:[]}});
  else if(!s.coachMemory)await saveSettings({coachMemory:{themes:['Rebuilding consistency after time away'],testing:[],decisions:['Keep the programme full-body while ski specificity rises gradually'],watch:[]}});
  // Canonical phase refresh. Older prototypes could leave duplicate/stale phase rows.
  s=await getSettings();
  if(s.phaseSeedVersion!=='2026-08-20-a'){await db.clear('phases');for(const p of PHASES)await db.add('phases',p);await saveSettings({phaseSeedVersion:'2026-08-20-a'});}
  if(!(await db.all('exceptions')).length)await db.add('exceptions',{name:'Christmas flexibility',from:'2026-12-21',to:'2027-01-01',projectionMode:'maintenance',excludeTDEE:true});
  if(!(await db.all('exercises')).length)await seedTraining();
  s=await getSettings();
  if(s.exerciseLibrarySeedVersion!=='2026-08-23-full'){
    await restoreExerciseLibrary();
    await saveSettings({exerciseLibrarySeedVersion:'2026-08-23-full'});
  }
  s=await getSettings();
  if(s.progressionSeedVersion!=='2026-08-21-a'){
    const exs=await db.all('exercises'), exName=Object.fromEntries(exs.map(e=>[e.id,e.name])), ts=await db.all('templates');
    for(const t of ts){
      if(t.type!=='strength'||!t.items)continue;
      let changed=false;
      for(const item of t.items){
        const name=exName[item.exerciseId]||'';
        const desired=name==='Pull Up'?'rep_only':name==='Loaded Inversions'?'rehab':(['Bulgarian Split Squat','Slow Step-down'].includes(name)?'manual':(item.progression||'double'));
        if(item.progression!==desired){item.progression=desired;changed=true}
      }
      if(changed)await db.put('templates',t);
    }
    await saveSettings({progressionSeedVersion:'2026-08-21-a'});
  }
  s=await getSettings();
  if(s.scheduleSeedVersion!=='2026-08-20-a'){await seedProgrammeSchedule();await saveSettings({scheduleSeedVersion:'2026-08-20-a'});}
}

async function restoreExerciseLibrary(){
  const existing=await db.all('exercises'),names=new Set(existing.map(e=>String(e.name||'').trim().toLowerCase()));
  const extra=[
    {name:'Slow Step-down',category:'Lower body',equipment:'Bodyweight / plate',loadType:'kg',increment:2.5,defaultRest:90,notes:'3–4 second lowering; eccentric control.'},
    {name:'Lateral Lunge',category:'Lower body',equipment:'Bodyweight / dumbbell',loadType:'kg',increment:2.5,defaultRest:90,notes:''}
  ];
  let added=0;
  for(const ex of [...RESTORED_EXERCISE_LIBRARY,...extra]){
    const key=ex.name.trim().toLowerCase();
    if(names.has(key))continue;
    await db.add('exercises',structuredClone(ex));names.add(key);added++
  }
  return added
}
