async function sendCoachMessage(isWeekly,ws,override=null,hiddenUser=false,retryExisting=false){
  const inp=$('#coachInput'),text=override||inp?.value.trim();if(!text)return;
  if(inp&&!retryExisting)inp.value='';
  const thread=await getCoachThread();
  if(!retryExisting){
    thread.messages.push({role:'user',content:text,hidden:hiddenUser,at:new Date().toISOString()});
    thread.messages=thread.messages.slice(-30);thread.updatedAt=new Date().toISOString();
    await db.put('aiReviews',thread);
    if(!hiddenUser)$('#chat')?.insertAdjacentHTML('beforeend',`<div class="msg user">${esc(text)}</div>`);
  }
  $('#coachError')?.remove();$('#thinking')?.remove();
  $('#chat')?.insertAdjacentHTML('beforeend','<div class="msg assistant" id="thinking">Thinking…</div>');
  const scrollChat=()=>{const c=$('#chat');if(c)c.scrollTop=c.scrollHeight};scrollChat();
  try{
    const key=`${isWeekly?'weekly':'open'}:${ws}`,sig=await coachContextSignature(ws);
    let sess=thread.sessions?.[key],resp;
    if(!sess?.responseId||sess.contextSignature!==sig){
      const first=await coachInitialPayload(thread.messages,isWeekly,ws);
      resp=await callOpenAI(first.input,{instructions:first.instructions});
      thread.sessions={...(thread.sessions||{}),[key]:{responseId:resp.id,startedAt:new Date().toISOString(),contextSignature:sig}}
    }else{
      resp=await callOpenAI(text,{previousResponseId:sess.responseId,instructions:coachContinuationInstructions()});
      thread.sessions[key].responseId=resp.id
    }
    if(!resp.text?.trim())throw new Error('Empty response from OpenAI');
    const {reply,memory}=parseCoachReply(resp.text);
    if(!reply)throw new Error('Empty response from OpenAI');
    $('#thinking')?.remove();
    $('#chat')?.insertAdjacentHTML('beforeend',`<div class="msg assistant">${esc(reply)}</div>`);
    thread.messages.push({role:'assistant',content:reply,at:new Date().toISOString()});
    thread.messages=thread.messages.slice(-30);thread.updatedAt=new Date().toISOString();
    await db.put('aiReviews',thread);
    if(memory){
      const settings=await getSettings(),current=settings.coachMemory||{themes:[],testing:[],decisions:[],watch:[]},merged={...current};
      for(const k of ['themes','testing','decisions','watch'])if(Array.isArray(memory[k])&&memory[k].length)merged[k]=memory[k];
      await saveSettings({coachMemory:merged})
    }
    if(isWeekly){
      let review=(await db.all('weeklyReviews')).find(r=>r.weekStart===ws);
      if(review){review.coachResponse=reply;review.updatedAt=isoDate();await db.put('weeklyReviews',review)}
    }
    scrollChat()
  }catch(e){
    $('#thinking')?.remove();
    $('#chat')?.insertAdjacentHTML('beforeend',`<div class="msg assistant coach-error" id="coachError">${esc(friendlyAIError(e))} <button class="linkbtn" id="retryCoach">Try again</button></div>`);
    $('#retryCoach')?.addEventListener('click',()=>sendCoachMessage(isWeekly,ws,text,hiddenUser,true));
    scrollChat();
    console.error('Slope Coach error',e)
  }
}
function hashString(v){let h=2166136261;for(let i=0;i<v.length;i++){h^=v.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(36)}
async function coachContextSignature(ws){return hashString(JSON.stringify(await compileCoachContext(ws)))}
function coachContinuationInstructions(){return`Continue as Gareth's long-term training and ski-preparation coach. Be conversational, grounded and supportive without becoming a dashboard. Use the established context from the previous response. Ask only targeted questions when needed. At the end append the hidden memory block exactly as previously instructed.`}
async function coachInitialPayload(messages,isWeekly,ws){const [s,phases,reviews]=await Promise.all([getSettings(),db.all('phases'),db.all('weeklyReviews')]),phase=currentPhase(phases),context=await compileCoachContext(ws),memory=s.coachMemory||{},review=reviews.find(r=>r.weekStart===ws);const instructions=`You are the long-term personal training, ski-preparation and practical life coach inside Gareth's private app. You are a partner, not a calculator or compliance bot. Gareth can read his own numbers. Use data as evidence only when it changes the judgement. Be warm, grounded and conversational without fake enthusiasm. Credit things genuinely earned. Challenge repeated avoidance when evidence supports it, but never shame. Distinguish a hard week, poor adherence, bad planning and bad luck. Sometimes the answer is do less; sometimes it is to stop avoiding the session. Goals: arrive at Les Carroz on 9 Jan 2027 lighter, stronger, fitter and skiing better; keep a recognisable full-body A/B programme while ski specificity rises; use Les Carroz as evidence for Flaine on 27 Mar 2027; build routines that survive real life. Current phase: ${phase.name}: ${phase.summary}. Rules: ${(phase.rules||[]).join('; ')}. Targets: calories ${s.calorieLow}-${s.calorieHigh}; ParrotPal ${s.externalCalories}; protein floor ${s.proteinFloor}g preferred ${s.proteinPreferred}g; steps ${s.stepTarget}/day. Coach memory: ${JSON.stringify(memory)}. Do not make Gareth repeat context already supplied. Ask at most one or two targeted questions if missing facts materially change advice. Use schedule-change history and the longView block to distinguish a noisy week from a multi-week or multi-phase pattern. Use liftTrend for genuine progression/stalls, monthly weight averages for body-composition context, and repeated moves/skips as evidence of plan friction without moralising. Be conservative about changing calories/training from one noisy week. Do not diagnose injury. Weekly check-ins should leave him with a simple approach to next week. Replies are usually 2-6 short paragraphs. At the very end append exactly <<<MEMORY_JSON>>>{"themes":[],"testing":[],"decisions":[],"watch":[]}<<<END_MEMORY>>> with concise updated memory.`;const visible=messages.filter(m=>!m.hidden).slice(-6).map(m=>`${m.role.toUpperCase()}: ${m.content}`).join('\n');const input=`MODE: ${isWeekly?'WEEKLY CHECK-IN':'OPEN COACH CONVERSATION'}${review?`\nWeekly mood: ${review.mood||'not stated'}\nExtra context: ${review.context||'none'}`:''}\n\nAUTOMATIC CONTEXT\n${JSON.stringify(context)}\n\nRECENT CONVERSATION\n${visible||'none'}\n\nCURRENT USER TURN\n${messages.at(-1)?.content||''}`;return{instructions,input}}
function monthKey(date){return String(date||'').slice(0,7)}
function e1rm(weight,reps){weight=Number(weight);reps=Number(reps);return Number.isFinite(weight)&&weight>0&&Number.isFinite(reps)&&reps>0?weight*(1+reps/30):null}
