  for(const a of audit.filter(x=>x.action==='moved')){const date=a.after?.date||a.toDate||a.at?.slice(0,10),ph=phaseForDate(phases,date);if(ph){const x=phaseMap[ph.id]??={phase:ph.name,planned:0,done:0,moved:0,skipped:0};x.moved++;phaseMap[ph.id]=x}}
  const perLift={};[...workouts].sort((a,b)=>a.date.localeCompare(b.date)).forEach(w=>(w.items||[]).forEach(it=>{const vals=(it.sets||[]).filter(s=>s.type==='work'&&s.reps).map(s=>({date:w.date,e1rm:e1rm(s.weight,s.reps)})).filter(x=>x.e1rm);if(vals.length)(perLift[it.name]??=[]).push(...vals)}));
  const liftTrend=Object.entries(perLift).map(([name,vals])=>{const first=vals[0],latest=vals.at(-1),best=vals.reduce((a,b)=>!a||b.e1rm>a.e1rm?b:a,null);return{name,first:Number(first.e1rm.toFixed(1)),latest:Number(latest.e1rm.toFixed(1)),changePct:Number(((latest.e1rm/first.e1rm-1)*100).toFixed(0)),lastPB:best.date,stalledWeeks:Math.max(0,Math.floor((parseDate(isoDate())-parseDate(best.date))/604800000))}}).sort((a,b)=>Math.abs(b.changePct)-Math.abs(a.changePct)).slice(0,12);
  const snow={};acts.filter(x=>x.kind==='snow').forEach(x=>snow[monthKey(x.date)]=(snow[monthKey(x.date)]||0)+(Number(x.minutes)||0));
  const skips={};planned.filter(x=>x.status==='skipped'&&x.skipReason).forEach(x=>skips[x.skipReason]=(skips[x.skipReason]||0)+1);
  const moves={};audit.filter(x=>x.action==='moved'&&x.title).forEach(x=>moves[x.title]=(moves[x.title]||0)+1);
  return{weightByMonth:weightByMonth.slice(-8),adherenceByPhase:Object.values(phaseMap),liftTrend,snowMinutesByMonth:Object.entries(snow).sort().slice(-8).map(([month,minutes])=>({month,minutes})),recurringSkipReasons:Object.entries(skips).sort((a,b)=>b[1]-a[1]).slice(0,6).map(([reason,count])=>({reason,count})),frequentlyMovedSessions:Object.entries(moves).sort((a,b)=>b[1]-a[1]).slice(0,6).map(([title,count])=>({title,count}))}
