function buildLiftRows(workouts){const map={};[...workouts].sort((a,b)=>a.date.localeCompare(b.date)).forEach(w=>(w.items||[]).forEach(it=>{const vals=(it.sets||[]).filter(s=>s.type==='work'&&s.reps).map(s=>({date:w.date,e1rm:e1rm(s.weight,s.reps)})).filter(x=>x.e1rm);if(vals.length)(map[it.name]??=[]).push({date:w.date,best:Math.max(...vals.map(x=>x.e1rm))})}));return Object.entries(map).map(([name,x])=>{const first=x[0],latest=x.at(-1);return{name,sessions:new Set(x.map(z=>z.date)).size,first:first.best,latest:latest.best,latestDate:latest.date,changePct:first.best?Math.round((latest.best/first.best-1)*100):null,points:x}}).sort((a,b)=>Math.abs(b.changePct||0)-Math.abs(a.changePct||0))}
function openLiftDetail(name,workouts){const row=buildLiftRows(workouts).find(x=>x.name===name);if(!row)return;const w=560,h=120,p=10,vals=row.points.map(x=>x.best),min=Math.min(...vals)*.96,max=Math.max(...vals)*1.04||1,pts=row.points.map((x,i)=>`${p+i*(w-2*p)/Math.max(1,row.points.length-1)},${h-p-(x.best-min)*(h-2*p)/Math.max(.1,max-min)}`).join(' ');showSheet(`<div class="sheethead"><div><div class="eyebrow">Lift trend</div><h2>${esc(name)}</h2></div><button class="btn small ghost" data-close>Close</button></div><svg class="lift-chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><polyline points="${pts}" fill="none" stroke="var(--blue)" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg><div class="small muted">Estimated 1RM is only a comparison tool here; it is not a max-test prescription.</div><div style="margin-top:12px">${row.points.slice(-8).reverse().map(x=>`<div class="metric-row"><span>${fmt(x.date)}</span><strong>${x.best.toFixed(1)}</strong></div>`).join('')}</div>`)}
function openWorkoutHistory(workouts){const xs=[...workouts].sort((a,b)=>b.date.localeCompare(a.date));showSheet(`<div class="sheethead"><div><div class="eyebrow">Strength history</div><h2>Workouts</h2></div><button class="btn small ghost" data-close>Close</button></div>${xs.map(w=>`<button class="item workout-history-row" data-hist-workout="${w.id}" style="width:100%;text-align:left"><div class="row"><div><strong>${esc(w.templateName||'Workout')}</strong><div class="tiny muted">${fmt(w.date)} · ${w.items?.length||0} exercises</div></div><span>›</span></div></button>`).join('')||'<div class="muted">No workouts yet.</div>'}`,{full:true});$$('[data-hist-workout]').forEach(b=>b.onclick=()=>openWorkoutDetail(Number(b.dataset.histWorkout),()=>openWorkoutHistory(workouts)))}

function weightTrend(weights){if(!weights.length)return{};const now=new Date(),recent=days=>weights.filter(x=>(now-parseDate(x.date))/86400000<days);const a7=avg(recent(7).map(x=>x.weight)),r28=recent(28);let rate=null;if(r28.length>=4){const n=Math.max(2,Math.floor(r28.length/3)),a=avg(r28.slice(0,n).map(x=>x.weight)),b=avg(r28.slice(-n).map(x=>x.weight)),days=(parseDate(r28.at(-1).date)-parseDate(r28[0].date))/86400000;rate=(b-a)/(Math.max(7,days)/7)}return{avg7:a7,current:weights.at(-1).weight,rate}}
function estimateBMR(s,weight){if(!weight||!s.heightCm||!s.birthDate)return null;const born=parseDate(s.birthDate),now=new Date();let age=now.getFullYear()-born.getFullYear();if(now<new Date(now.getFullYear(),born.getMonth(),born.getDate()))age--;const base=10*weight+6.25*Number(s.heightCm)-5*age;return base+(s.sex==='female'?-161:5)}
function estimateTDEE(daily){const xs=daily.filter(x=>x.calories&&x.weight).sort((a,b)=>a.date.localeCompare(b.date));if(xs.length<21)return null;const r=xs.slice(-35),c=avg(r.map(x=>x.calories)),n=Math.max(3,Math.floor(r.length/4)),first=avg(r.slice(0,n).map(x=>x.weight)),last=avg(r.slice(-n).map(x=>x.weight)),days=(parseDate(r.at(-1).date)-parseDate(r[0].date))/86400000||1;return c-((last-first)/days)*7700}
function weightSVG(weights){if(weights.length<2)return'<div class="empty">Two weigh-ins are enough to start drawing the line.</div>';const p=weights.slice(-60),v=p.map(x=>x.weight),min=Math.min(...v)-.4,max=Math.max(...v)+.4,w=600,h=140,pad=8,pts=p.map((x,i)=>`${pad+i*(w-2*pad)/(p.length-1)},${h-pad-(x.weight-min)*(h-2*pad)/(max-min)}`).join(' ');return `<svg class="spark" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><polyline points="${pts}" fill="none" stroke="#4f78b8" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg>`}
function projectionRow(g,t,exceptions=[]){if(!t.current)return`<div class="metric-row"><span>${esc(g.name)} · ${fmt(g.date)}</span><strong>—</strong></div>`;if(t.rate==null)return`<div class="metric-row"><div><strong>${esc(g.name)}</strong><div class="tiny muted">${fmt(g.date)}</div></div><div style="text-align:right"><strong>—</strong><div class="tiny muted">not enough trend data</div></div></div>`;const days=Math.max(0,daysUntil(g.date)),today=parseDate(isoDate()),goal=parseDate(g.date);let maintenance=0;for(const ex of exceptions.filter(x=>x.projectionMode==='maintenance')){const from=parseDate(ex.from),to=parseDate(ex.to),a=today>from?today:from,b=goal<to?goal:to;if(b>a)maintenance+=(b-a)/86400000}const proj=t.current+t.rate*(Math.max(0,days-maintenance)/7);return`<div class="metric-row"><div><strong>${esc(g.name)}</strong><div class="tiny muted">${fmt(g.date)}</div></div><div style="text-align:right"><strong>${proj.toFixed(1)} kg</strong><div class="tiny muted">measured trend · ${Math.round(maintenance)} maintenance days</div></div></div>`}
async function renderMore(){const [s,phases,templates,exs]=await Promise.all([getSettings(),db.all('phases'),db.all('templates'),db.all('exercises')]);const phase=currentPhase(phases),backupDays=s.lastBackupAt?Math.floor((Date.now()-new Date(s.lastBackupAt))/86400000):null,backupOld=backupDays==null||backupDays>=21;$('#app').innerHTML=`<div class="top"><div><div class="eyebrow">Under the bonnet</div><h1>More</h1></div></div>${backupOld?`<section class="backup-nag"><strong>${backupDays==null?'No backup yet':`Last backup ${backupDays} days ago`}</strong><span>This app is local-only. Take 20 seconds and keep the last few months survivable.</span><button class="btn small" id="nagBackup">Back up now</button></section>`:''}<section class="card" id="birdPlan"><div class="row"><div><h3>Bird’s-eye plan</h3><div class="small muted" style="margin-top:4px">Current: ${esc(phase.name)} · every phase visible now</div></div><strong>›</strong></div></section><section class="card" id="templatesBtn"><div class="row"><div><h3>Templates & exercises</h3><div class="small muted" style="margin-top:4px">${templates.length} templates · ${exs.length} exercises · fully editable</div></div><strong>›</strong></div></section><section class="card" id="targetsBtn"><div class="row"><div><h3>Targets</h3><div class="small muted" style="margin-top:4px">${s.calorieLow}–${s.calorieHigh} kcal · ${s.proteinFloor}g protein floor · ${Number(s.stepTarget||0).toLocaleString()} steps</div></div><strong>›</strong></div></section><section class="card" id="aiSettings"><div class="row"><div><h3>AI Coach</h3><div class="small muted" style="margin-top:4px">${localStorage.getItem('openaiKey')?'Connected locally':'Not connected'} · ${esc(s.aiModel||'gpt-5.6')}</div></div><strong>›</strong></div></section><section class="card"><div class="row"><div><h3>Backup</h3><div class="small muted" style="margin-top:4px">API key is never included.${s.lastBackupAt?` Last backup ${new Date(s.lastBackupAt).toLocaleDateString('en-GB')}.`:''}</div></div></div><div class="wrap" style="margin-top:12px"><button class="btn secondary" id="exportBtn">Export / share backup</button><label class="btn secondary" style="margin:0">Restore<input id="restoreFile" type="file" accept=".json" hidden></label></div></section><div class="tiny muted" style="text-align:center;margin-top:20px">Slope v${VERSION}</div>`;$('#birdPlan').onclick=()=>openBird(phases);$('#templatesBtn').onclick=openTemplateLibrary;$('#targetsBtn').onclick=()=>openTargets(s);$('#aiSettings').onclick=()=>openAISettings(s);$('#exportBtn').onclick=exportData;$('#nagBackup')?.addEventListener('click',exportData);$('#restoreFile').onchange=restoreData}

function openBird(phases){const cur=currentPhase(phases);showSheet(`<div class="sheethead"><div><div class="eyebrow">Now → Flaine</div><h2>The whole plan</h2></div><button class="btn small ghost" data-close>Close</button></div>${[...phases].filter(p=>p.from).sort((a,b)=>a.from.localeCompare(b.from)).map(p=>`<div class="phase ${p.id===cur.id?'current':''}"><h3>${esc(p.name)}</h3><div class="tiny muted">${fmt(p.from)} → ${fmt(p.to)}</div><p class="small">${esc(p.summary)}</p><div class="tiny muted">${(p.rules||[]).map(esc).join(' · ')}</div></div>`).join('')}`,{full:true})}
async function openTemplateLibrary(){const ts=await db.all('templates');showSheet(`<div class="sheethead"><div><div class="eyebrow">Training machinery</div><h2>Templates</h2></div><button class="btn small ghost" data-close>Close</button></div>${ts.map(t=>`<section class="card"><div class="row"><div><h3>${esc(t.name)}</h3><div class="small muted">${esc(t.description||t.type)}</div></div><button class="btn small blue" data-template-start="${t.id}">Start</button></div><div class="wrap" style="margin-top:10px"><button class="btn small secondary" data-template-edit="${t.id}">Edit</button><button class="btn small ghost" data-template-copy="${t.id}">Duplicate</button><button class="btn small danger" data-template-del="${t.id}">Delete</button></div></section>`).join('')}<button class="btn blue block" id="newTemplate">+ New template</button><button class="btn secondary block" id="exerciseLib" style="margin-top:9px">Exercise library</button>`,{full:true});$$('[data-template-start]').forEach(b=>b.onclick=async()=>{const t=await db.get('templates',Number(b.dataset.templateStart));closeSheet();if(t.type==='strength')startWorkout(t);else openActivity(t.type,null,t)});$$('[data-template-edit]').forEach(b=>b.onclick=async()=>editTemplate(await db.get('templates',Number(b.dataset.templateEdit)),openTemplateLibrary));$$('[data-template-copy]').forEach(b=>b.onclick=async()=>{const t=structuredClone(await db.get('templates',Number(b.dataset.templateCopy)));delete t.id;t.name+=' copy';await db.add('templates',t);openTemplateLibrary()});$$('[data-template-del]').forEach(b=>b.onclick=async()=>{const id=Number(b.dataset.templateDel),t=await db.get('templates',id),future=(await db.all('planned')).filter(p=>p.templateId===id&&p.date>=isoDate());if(future.length){toast(`${future.length} future planned session${future.length===1?'':'s'} still use ${t.name}. Reassign them first.`);return}const ok=await confirmAction({title:'Delete template?',message:`Delete ${t.name}? Completed workout history stays intact.`,confirmLabel:'Delete',danger:true,onCancel:openTemplateLibrary});if(ok){await db.del('templates',id);openTemplateLibrary()}});$('#newTemplate').onclick=()=>editTemplate(null,openTemplateLibrary);$('#exerciseLib').onclick=()=>openExerciseLibrary(openTemplateLibrary)}
async function editTemplate(t=null,returnTo=null){const exs=await db.all('exercises'),d=t?structuredClone(t):{name:'New template',type:'strength',description:'',items:[],activity:{kind:'Easy / Zone 2',minutes:45,focus:''}};const draw=()=>{showSheet(`<div class="sheethead"><div><div class="eyebrow">Template</div><h2>${esc(d.name)}</h2></div><button class="btn small ghost" data-close>Close</button></div><div class="field"><label>Name</label><input id="teName" value="${esc(d.name)}"></div><div class="field"><label>Type</label><select id="teType"><option value="strength" ${d.type==='strength'?'selected':''}>Strength</option><option value="cardio" ${d.type==='cardio'?'selected':''}>Cardio</option><option value="snow" ${d.type==='snow'?'selected':''}>Snow / Snozone</option><option value="other" ${d.type==='other'?'selected':''}>Other</option></select></div><div class="field"><label>Description</label><input id="teDesc" value="${esc(d.description||'')}"></div>${d.type==='strength'?`${d.items.map((x,i)=>{const e=exs.find(z=>z.id===x.exerciseId);return`<section class="card teitem"><div class="row"><strong>${esc(e?.name||'Unknown')}</strong><div class="wrap"><button class="btn small ghost" data-te-up="${i}" aria-label="Move exercise up">↑</button><button class="btn small ghost" data-te-down="${i}" aria-label="Move exercise down">↓</button><button class="btn small danger" data-te-del="${i}" aria-label="Remove exercise">×</button></div></div><div class="grid4" style="margin-top:10px">${tplField('Sets','sets',x.sets,i)}${tplField('Rep min','repMin',x.repMin,i)}${tplField('Rep max','repMax',x.repMax,i)}${tplField('Target','target',x.target,i)}${tplField('Rest','rest',x.rest,i)}${tplField('Start kg','startWeight',x.startWeight,i)}${tplField('Later sets','eventualSets',x.eventualSets,i)}</div><div class="field"><label>Warm-ups <span class="muted">comma separated, e.g. 20×10, 40×5</span></label><input data-tpl-warm="${i}" value="${esc((x.warmups||[]).map(w=>w.label).join(', '))}"></div><div class="field"><label>Note</label><input data-tpl="${i}:note" value="${esc(x.note||'')}"></div><div class="field"><label>Progression</label><select data-tpl-progression="${i}"><option value="double" ${(x.progression||'double')==='double'?'selected':''}>Double progression</option><option value="rep_only" ${x.progression==='rep_only'?'selected':''}>Reps / quality only</option><option value="manual" ${x.progression==='manual'?'selected':''}>Manual / technique-led</option><option value="rehab" ${x.progression==='rehab'?'selected':''}>Rehab / manual</option></select></div><div class="wrap"><label class="check-label"><input type="checkbox" data-tpl-flag="${i}:optional" ${x.optional?'checked':''}> Optional</label><label class="check-label"><input type="checkbox" data-tpl-flag="${i}:rehab" ${x.rehab?'checked':''}> Rehab</label></div></section>`}).join('')}<div class="field"><label>Add exercise</label><input id="tplExSearch" placeholder="Search the exercise library…"></div><div class="row"><select id="tplAddEx"><option value="">Choose exercise…</option>${[...exs].sort((a,b)=>a.name.localeCompare(b.name)).map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select><button class="btn small blue" id="tplAdd">Add</button></div>`:`<section class="card"><div class="field"><label>Activity label</label><input id="actKind" value="${esc(d.activity?.kind||d.name)}"></div><div class="field"><label>Default minutes</label><input id="actMins" inputmode="numeric" value="${d.activity?.minutes??45}"></div><div class="field"><label>${d.type==='snow'?'Default technical focus':'Default note / focus'}</label><input id="actFocus" value="${esc(d.activity?.focus||'')}"></div></section>`}<div class="wrap"><button class="btn blue" id="saveTemplate">Save template</button>${d.id?'<button class="btn secondary" id="copyTemplate">Save as copy</button>':''}</div>`,{full:true,returnTo});const capture=()=>{d.name=$('#teName').value.trim()||'Untitled template';d.type=$('#teType').value;d.description=$('#teDesc').value.trim();if(d.type==='strength'){$$('[data-tpl]').forEach(el=>{const [i,f]=el.dataset.tpl.split(':');d.items[Number(i)][f]=f==='note'?el.value:num(el.value)});$$('[data-tpl-warm]').forEach(el=>{d.items[Number(el.dataset.tplWarm)].warmups=el.value.split(',').map(x=>x.trim()).filter(Boolean).map(label=>({label}))});$$('[data-tpl-progression]').forEach(el=>{d.items[Number(el.dataset.tplProgression)].progression=el.value});$$('[data-tpl-flag]').forEach(el=>{const [i,f]=el.dataset.tplFlag.split(':');d.items[Number(i)][f]=el.checked})}else d.activity={kind:$('#actKind')?.value.trim()||d.name,minutes:num($('#actMins')?.value)??45,focus:$('#actFocus')?.value.trim()||''}};$('#teType').onchange=()=>{capture();d.type=$('#teType').value;state.sheetReturn=null;closeSheet();draw()};$$('[data-te-del]').forEach(b=>b.onclick=()=>{capture();d.items.splice(Number(b.dataset.teDel),1);state.sheetReturn=null;closeSheet();draw()});$$('[data-te-up]').forEach(b=>b.onclick=()=>{capture();const i=Number(b.dataset.teUp);if(i>0)[d.items[i-1],d.items[i]]=[d.items[i],d.items[i-1]];state.sheetReturn=null;closeSheet();draw()});$$('[data-te-down]').forEach(b=>b.onclick=()=>{capture();const i=Number(b.dataset.teDown);if(i<d.items.length-1)[d.items[i+1],d.items[i]]=[d.items[i],d.items[i+1]];state.sheetReturn=null;closeSheet();draw()});$('#tplExSearch')?.addEventListener('input',()=>{const q=$('#tplExSearch').value.toLowerCase().trim(),sel=$('#tplAddEx'),current=sel.value;sel.innerHTML='<option value="">Choose exercise…</option>'+[...exs].sort((a,b)=>a.name.localeCompare(b.name)).filter(e=>!q||`${e.name} ${e.category} ${e.equipment}`.toLowerCase().includes(q)).map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('');if([...sel.options].some(o=>o.value===current))sel.value=current});$('#tplAdd')?.addEventListener('click',()=>{capture();const eid=Number($('#tplAddEx').value);if(eid){const e=exs.find(x=>x.id===eid);d.items.push({exerciseId:eid,sets:2,repMin:8,repMax:12,target:8,rest:e.defaultRest||90,startWeight:0,eventualSets:3,optional:false,rehab:false,note:'',warmups:[],progression:'double'});state.sheetReturn=null;closeSheet();draw()}});$('#saveTemplate').onclick=async()=>{capture();if(d.id)await db.put('templates',d);else d.id=await db.add('templates',d);state.sheetReturn=null;closeSheet();openTemplateLibrary()};$('#copyTemplate')?.addEventListener('click',async()=>{capture();const c=structuredClone(d);delete c.id;c.name+=' copy';await db.add('templates',c);state.sheetReturn=null;closeSheet();openTemplateLibrary()})};draw()}
function tplField(label,f,v,i){return`<div class="field"><label>${label}</label><input data-tpl="${i}:${f}" inputmode="decimal" value="${v??''}"></div>`}
async function openExerciseLibrary(returnTo=null){
  const exs=(await db.all('exercises')).sort((a,b)=>a.name.localeCompare(b.name)),categories=['All',...new Set(exs.map(e=>e.category||'Other'))].sort((a,b)=>a==='All'?-1:b==='All'?1:a.localeCompare(b));
  showSheet(`<div class="sheethead"><div><div class="eyebrow">Library</div><h2>Exercises <span class="muted">· ${exs.length}</span></h2></div><button class="btn small ghost" data-close>Close</button></div><div class="library-tools"><input id="exerciseSearch" placeholder="Search exercise, equipment or category…" autocomplete="off"><select id="exerciseCategory">${categories.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select></div><div id="exerciseResults"></div><button class="btn blue block" id="newExercise">+ New exercise</button>`,{full:true,returnTo});
  const draw=()=>{
    const q=$('#exerciseSearch').value.trim().toLowerCase(),cat=$('#exerciseCategory').value;
    const filtered=exs.filter(e=>(cat==='All'||e.category===cat)&&(!q||`${e.name} ${e.category} ${e.equipment}`.toLowerCase().includes(q)));
    $('#exerciseResults').innerHTML=filtered.length?filtered.map(e=>`<div class="card-flat"><div class="row"><div><strong>${esc(e.name)}</strong><div class="tiny muted">${esc(e.category||'Other')} · ${esc(e.equipment||'')}</div></div><div class="wrap"><button class="btn small ghost" data-ex-edit="${e.id}">Edit</button><button class="btn small danger" data-ex-del="${e.id}">Delete</button></div></div></div>`).join(''):'<div class="empty">No exercises match that search.</div>';
    $$('[data-ex-edit]').forEach(b=>b.onclick=async()=>editExercise(await db.get('exercises',Number(b.dataset.exEdit)),()=>openExerciseLibrary(returnTo)));
    $$('[data-ex-del]').forEach(b=>b.onclick=async()=>{const id=Number(b.dataset.exDel),e=await db.get('exercises',id),templates=await db.all('templates'),used=templates.filter(t=>t.items?.some(x=>x.exerciseId===id));if(used.length){toast(`${e.name} is used in ${used.length} template${used.length===1?'':'s'}. Remove it there first.`);return}const ok=await confirmAction({title:'Delete exercise?',message:`Delete ${e.name} from the exercise library? Historical workout logs stay intact.`,confirmLabel:'Delete',danger:true,onCancel:()=>openExerciseLibrary(returnTo)});if(ok){await db.del('exercises',id);openExerciseLibrary(returnTo)}})
  };
  $('#exerciseSearch').oninput=draw;$('#exerciseCategory').onchange=draw;$('#newExercise').onclick=()=>editExercise(null,()=>openExerciseLibrary(returnTo));draw()
}
async function editExercise(e=null,returnTo=null){showSheet(`<div class="sheethead"><div><div class="eyebrow">Exercise</div><h2>${e?'Edit':'New'}</h2></div><button class="btn small ghost" data-close>Close</button></div>${simpleField('Name','exName',e?.name||'')}${simpleField('Category','exCat',e?.category||'')}${simpleField('Equipment','exEquip',e?.equipment||'')}<div class="field"><label>Load type</label><select id="exLoad"><option value="kg" ${e?.loadType==='kg'?'selected':''}>kg</option><option value="bodyweight" ${e?.loadType==='bodyweight'?'selected':''}>bodyweight</option><option value="assisted" ${e?.loadType==='assisted'?'selected':''}>assisted</option><option value="duration" ${e?.loadType==='duration'?'selected':''}>duration</option></select></div>${simpleField('Increment','exInc',e?.increment??2.5,'decimal')}${simpleField('Default rest','exRest',e?.defaultRest??90,'numeric')}<div class="field"><label>Notes</label><textarea id="exNotes">${esc(e?.notes||'')}</textarea></div><button class="btn blue block" id="saveExercise">Save</button>`,{returnTo});$('#saveExercise').onclick=async()=>{const o={id:e?.id,name:$('#exName').value,category:$('#exCat').value,equipment:$('#exEquip').value,loadType:$('#exLoad').value||'kg',increment:Number($('#exInc').value)||0,defaultRest:Number($('#exRest').value)||90,notes:$('#exNotes').value};e?await db.put('exercises',o):await db.add('exercises',Object.fromEntries(Object.entries(o).filter(([k])=>k!=='id')));state.sheetReturn=null;closeSheet();openExerciseLibrary(returnTo)}}
function simpleField(label,id,v,mode='text'){return`<div class="field"><label>${label}</label><input id="${id}" ${mode!=='text'?`inputmode="${mode}"`:''} value="${esc(v)}"></div>`}
function openTargets(s){showSheet(`<div class="sheethead"><div><div class="eyebrow">ParrotPal stays the food logger</div><h2>Targets</h2></div><button class="btn small ghost" data-close>Close</button></div>${simpleField('Calories low','calLow',s.calorieLow,'numeric')}${simpleField('Calories high','calHigh',s.calorieHigh,'numeric')}${simpleField('Current ParrotPal calorie target','extCal',s.externalCalories,'numeric')}${simpleField('Protein floor','proFloor',s.proteinFloor,'numeric')}${simpleField('Preferred protein','proPref',s.proteinPreferred,'numeric')}${simpleField('Steps/day','stepsTarget',s.stepTarget,'numeric')}<button class="btn blue block" id="saveTargets">Save</button>`);$('#saveTargets').onclick=async()=>{await saveSettings({calorieLow:num($('#calLow').value)??s.calorieLow,calorieHigh:num($('#calHigh').value)??s.calorieHigh,externalCalories:num($('#extCal').value)??s.externalCalories,proteinFloor:num($('#proFloor').value)??s.proteinFloor,proteinPreferred:num($('#proPref').value)??s.proteinPreferred,stepTarget:num($('#stepsTarget').value)??s.stepTarget});closeSheet();render()}}
function openAISettings(s){const has=!!localStorage.getItem('openaiKey');showSheet(`<div class="sheethead"><div><div class="eyebrow">Local AI</div><h2>Coach connection</h2></div><button class="btn small ghost" data-close>Close</button></div><div class="card" style="background:var(--amber-soft)"><p class="small" style="margin:0">The key lives only in this browser/device and is excluded from backup. Safari may evict local storage under pressure, in which case AI will simply show as disconnected. Use a dedicated API project/key with a low spend limit.</p></div><div class="field"><label>API key</label><input id="apiKey" type="password" value="${has?'••••••••••••••••••••':''}" placeholder="sk-..."></div><div class="field"><label>Model</label><input id="aiModel" value="${esc(s.aiModel||'gpt-5.6')}"></div><div class="wrap"><button class="btn blue" id="saveAI">Save locally</button><button class="btn secondary" id="testAI">Test</button>${has?'<button class="btn danger" id="removeAI">Remove</button>':''}</div><div id="aiStatus" class="small muted" style="margin-top:12px"></div>`);$('#saveAI').onclick=async()=>{const v=$('#apiKey').value;if(v&&!v.includes('•'))localStorage.setItem('openaiKey',v.trim());await saveSettings({aiModel:$('#aiModel').value.trim()||'gpt-5.6'});$('#aiStatus').textContent='Saved locally.'};$('#testAI').onclick=async()=>{const st=$('#aiStatus');st.textContent='Testing…';try{const out=await callOpenAI('Reply with exactly: connection works.',{maxOutputTokens:50});st.textContent=out.text.trim()}catch(e){st.textContent=friendlyAIError(e)}};$('#removeAI')?.addEventListener('click',()=>{localStorage.removeItem('openaiKey');closeSheet();render()})}
async function exportData(){const out={version:VERSION,exportedAt:new Date().toISOString(),stores:{}};for(const n of STORE_NAMES)out.stores[n]=await db.all(n);const text=JSON.stringify(out,null,2),name=`slope-backup-${isoDate()}.json`,file=new File([text],name,{type:'application/json'});let shared=false;try{if(navigator.share&&navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Slope backup'});shared=true}}catch(e){if(e.name!=='AbortError')console.warn(e)}if(!shared){const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(url);a.remove()},1200)}await saveSettings({lastBackupAt:new Date().toISOString()});toast(shared?'Backup shared':'Backup exported')}
async function restoreData(e){const f=e.target.files[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!data?.stores)throw new Error('Not a Slope backup');const counts=Object.fromEntries(Object.entries(data.stores).map(([k,v])=>[k,Array.isArray(v)?v.length:0]));showSheet(`<div class="sheethead"><div><div class="eyebrow">Restore preview</div><h2>${esc(f.name)}</h2></div><button class="btn small ghost" data-close>Cancel</button></div><div class="card"><div class="metric-row"><span>Backup version</span><strong>${esc(data.version||'unknown')}</strong></div><div class="metric-row"><span>Exported</span><strong>${data.exportedAt?new Date(data.exportedAt).toLocaleDateString('en-GB'):'unknown'}</strong></div><div class="metric-row"><span>Workouts</span><strong>${counts.workouts||0}</strong></div><div class="metric-row"><span>Daily logs</span><strong>${counts.daily||0}</strong></div><div class="metric-row"><span>Activities</span><strong>${counts.activities||0}</strong></div><div class="metric-row"><span>Coach records</span><strong>${(counts.aiReviews||0)+(counts.weeklyReviews||0)}</strong></div></div><div class="banner warn">Restoring replaces the local Slope data on this device. Your OpenAI API key is not affected.</div><button class="btn danger block" id="confirmRestore">Restore this backup</button>`);$('#confirmRestore').onclick=async()=>{for(const [n,xs] of Object.entries(data.stores||{})){if(!db.db.objectStoreNames.contains(n))continue;await db.clear(n);for(const x of xs)await db.put(n,structuredClone(x))}await seed();state.activeWorkout=null;localStorage.removeItem('slopeActiveWorkout');state.sheetReturn=null;closeSheet();toast('Restored');await render()}}catch(err){toast('Could not restore that backup')}finally{e.target.value=''}}


(async()=>{await db.init();if(navigator.storage?.persist)try{await navigator.storage.persist()}catch{}await seed();const active=localStorage.getItem('slopeActiveWorkout');if(active){try{state.activeWorkout=JSON.parse(active)}catch{}}if(window.visualViewport){const vv=()=>document.documentElement.style.setProperty('--vvh',window.visualViewport.height+'px');vv();window.visualViewport.addEventListener('resize',vv)}if('serviceWorker'in navigator){const reg=await navigator.serviceWorker.register('./sw.js');reg.addEventListener?.('updatefound',()=>toast('Slope updated. Reload if anything looks stale.'))}render()})();
